async page => {await page.emulateMedia({reducedMotion:'reduce'});return page.evaluate(async()=>{const nodes=[document.documentElement,...document.querySelectorAll('body,body *')],before=nodes.map(e=>({e,font:parseFloat(getComputedStyle(e).fontSize)})),first=parseFloat(getComputedStyle(document.querySelector('h1')).fontSize);before.forEach(({e,font})=>e.style.setProperty('font-size',font*2+'px','important'));await new Promise(r=>requestAnimationFrame(r));await Promise.all(document.getAnimations().filter(a=>a.effect.getComputedTiming().iterations!==Infinity).map(a=>a.finished.catch(()=>{})));for(let i=0;i<30&&parseFloat(getComputedStyle(document.querySelector('h1')).fontSize)!==first*2;i++)await new Promise(r=>setTimeout(r,50));if(parseFloat(getComputedStyle(document.querySelector('h1')).fontSize)!==first*2)throw new Error('Computed H1 must actually double');return {beforeH1:first,afterH1:parseFloat(getComputedStyle(document.querySelector('h1')).fontSize),rootFont:parseFloat(getComputedStyle(document.documentElement).fontSize),mode:'Measured200percentComputedTextEmulation',nativeMenuZoom:false};});}
